(()=>{const host=document.createElement('section');host.className='account-profile';host.setAttribute('aria-labelledby','profileHeading');document.querySelector('#accountIdentity').after(host);
host.innerHTML='<h3 id="profileHeading">Your profile</h3><p class="tiny">Keep your measurements and training preferences up to date. Saving recalculates nutrition targets from today; previous days keep their saved targets. This calculator supports adults aged 18–100.</p><form id="accountProfileForm"><div class="form-grid"><label>Date of birth<input type="date" name="dob" required autocomplete="bday"></label><label>Age<input name="age" type="text" readonly placeholder="Calculated from birth date" aria-live="polite"></label><label>Weight (kg)<input type="number" name="weight" min="35" max="250" step="0.1" inputmode="decimal" required></label><label>Height (cm)<input type="number" name="height" min="120" max="230" step="0.1" inputmode="decimal" required></label><label>Equation sex coefficient<select name="sex"></select></label><label>Your goal<select name="goal"></select></label><label>Activity level<select name="activity"></select></label></div><p id="profilePreview" class="plan-preview" role="status"></p><button class="primary full" type="submit">Save profile & update targets ↗</button><p id="profileFeedback" role="status" class="tiny"></p></form>';
const form=host.querySelector('form'),planForm=document.querySelector('#planForm'),feedback=host.querySelector('#profileFeedback');for(const key of ['sex','goal','activity'])form.elements[key].innerHTML=planForm.elements[key].innerHTML;
function preview(){const age=ProfileCore.ageAt(form.elements.dob.value,dateKey());form.elements.age.value=age===null?'':age+' years';form.elements.dob.setCustomValidity(age!==null&&(age<18||age>100)?'The nutrition calculator supports adults aged 18–100.':'');const data=values(age);host.querySelector('#profilePreview').textContent=age!==null&&age>=18&&age<=100&&data.weight>=35&&data.weight<=250&&data.height>=120&&data.height<=230?(()=>{const p=calculatePlan(data);return 'Updated daily targets: '+number(p.calories)+' kcal · '+p.protein+' g protein · '+p.carbs+' g carbs · '+p.fat+' g fat';})():'Enter a valid birth date and measurements to preview your targets.';}
function values(age){return {dob:form.elements.dob.value,age,weight:Number(form.elements.weight.value),height:Number(form.elements.height.value),sex:form.elements.sex.value,goal:form.elements.goal.value,activity:Number(form.elements.activity.value)};}
function fill(){form.elements.dob.max=dateKey();const p=state.profile||state.plan||{};for(const key of ['dob','weight','height'])form.elements[key].value=p[key]??'';for(const key of ['sex','goal','activity']){const v=p[key]??state.plan?.[key];if(v!==undefined)form.elements[key].value=v;}feedback.textContent='';preview();}
form.addEventListener('input',preview);form.addEventListener('change',preview);form.onsubmit=e=>{e.preventDefault();preview();if(!form.reportValidity())return;const age=ProfileCore.ageAt(form.elements.dob.value,dateKey());if(age===null)return;const previousProfile=state.profile,previousPlan=state.plan;const data=values(age);state.profile={...data,updatedAt:new Date().toISOString()};state.plan=calculatePlan(data);if(!save()){state.profile=previousProfile;state.plan=previousPlan;feedback.textContent='Profile could not be saved. Your previous profile and targets were kept.';return;}renderNutrition();feedback.textContent='Profile saved. Age is calculated from your birth date; targets apply from '+dateKey()+'. Check the account save status below for cloud confirmation.';};
window.AccountProfile={fillPlan(target){if(!state.profile)return;for(const key of ['weight','height','sex','goal','activity'])target.elements[key].value=state.profile[key];const age=ProfileCore.ageAt(state.profile.dob,dateKey());if(age!==null){target.elements.age.value=age;target.elements.age.readOnly=true;target.elements.age.title='Calculated from the date of birth in Your account';}},refresh:fill};document.querySelector('#accountButton').addEventListener('click',fill);fill();})();

